function renderFunnelStatistic(a,n,e){var t={type:"funnel",data:{datasets:[{data:a,backgroundColor:n}],labels:e},options:{responsive:!1,sort:"desc",legend:{display:!1,position:"right"},legendCallback:function(a){var n=[];n.push('<ul class="funnel-legend">');for(var e=0;e<a.data.datasets[0].data.length;e++)n.push('<li><i class="ui icon circle" style="color:'+a.data.datasets[0].backgroundColor[e]+'"></i> <span>'),a.data.labels[e]&&n.push(a.data.labels[e]),n.push("</span></li>");return n.push("</ul>"),n.join("")},animation:{animateScale:!0,animateRotate:!0}}},l=document.getElementById("funnel").getContext("2d");window.myDoughnut=new Chart(l,t),$("#funnel-container").append(window.myDoughnut.generateLegend())}